import{_ as o,o as a,c as r,ai as n}from"./chunks/framework.Ba-VnP44.js";const c=JSON.parse('{"title":"AI 能做什么、不能做什么","description":"","frontmatter":{},"headers":[],"relativePath":"ai/cognition/tech-boundary.md","filePath":"ai/cognition/tech-boundary.md"}'),i={name:"ai/cognition/tech-boundary.md"};function l(s,t,e,g,h,u){return a(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="ai-能做什么、不能做什么" tabindex="-1">AI 能做什么、不能做什么 <a class="header-anchor" href="#ai-能做什么、不能做什么" aria-label="Permalink to “AI 能做什么、不能做什么”">​</a></h1><p>用好 AI 的前提，是知道它的边界。高估能力会踩坑，低估能力会浪费。这一篇讲清楚：哪些事放心交给它，哪些事必须自己把关，以及人机之间怎么分工。</p><h2 id="为什么关注" tabindex="-1">为什么关注 <a class="header-anchor" href="#为什么关注" aria-label="Permalink to “为什么关注”">​</a></h2><p>刚接触 AI 时，人容易在两个极端之间摇摆：一会儿觉得它什么都能干，一会儿被它一本正经的胡说八道气到想卸载。两个极端都会导致同一个结果——用不好。</p><p>我身边见过两类典型翻车。一类是完全信任：让 AI 直接生成数据库迁移脚本，没审查就上线，字段类型错了半张表。另一类是完全不信：同事用 AI 十分钟做完的信息检索，他坚持手工查两小时，效率还不如不用。</p><p>更深层的原因是：我们习惯用&quot;人&quot;的标准去理解 AI。它说话有条理、有引用、语气自信，我们就默认它&quot;懂了&quot;。但它不是懂了，它是在生成最可能的下一段文字。理解这个本质，很多幻觉问题就不再是玄学，而是可预期、可设防的。</p><h2 id="方法与要点" tabindex="-1">方法与要点 <a class="header-anchor" href="#方法与要点" aria-label="Permalink to “方法与要点”">​</a></h2><h3 id="一、ai-的能力边界-它擅长什么" tabindex="-1">一、AI 的能力边界：它擅长什么 <a class="header-anchor" href="#一、ai-的能力边界-它擅长什么" aria-label="Permalink to “一、AI 的能力边界：它擅长什么”">​</a></h3><p>AI 的优势有清晰的模式：</p><ul><li><strong>模式识别与生成</strong>：从大量文本里找规律、按格式产出内容——摘要、翻译、改写、初稿。</li><li><strong>跨领域综合</strong>：把分散的信息快速组织成一个结构化的回答。</li><li><strong>不知疲倦的执行</strong>：批量处理、格式转换、代码模板、重复性改写。</li><li><strong>无压力的对话</strong>：随时追问、换个角度再解释一遍，不带情绪。</li></ul><p>一句话概括：<strong>凡是&quot;有明确模式、容错空间大、错了容易发现&quot;的事，AI 的性价比都很高。</strong></p><h3 id="二、它不能做什么" tabindex="-1">二、它不能做什么 <a class="header-anchor" href="#二、它不能做什么" aria-label="Permalink to “二、它不能做什么”">​</a></h3><ul><li><strong>幻觉</strong>：这是最核心的限制。模型会生成看似合理但事实错误的内容——编造论文、编造 API、编造数字。原因不是&quot;不够聪明&quot;，而是它的目标是生成通顺的文本，不是生成正确的事实。越是冷门、越是需要精确的内容，越要警惕。</li><li><strong>不能为决策负责</strong>：它可以给你选项和分析，但选错了没有人替你承担后果——除了你自己。</li><li><strong>不了解你的上下文</strong>：你没告诉它的项目历史、客户偏好、组织政治，它一概不知道，但它会用自信的语气补齐这些空白。</li><li><strong>不能访问真实世界</strong>：除非接了工具，否则它不知道今天天气、不知道你代码仓库的最新状态、不知道刚开完的会决定了什么。</li><li><strong>长链条推理易断</strong>：步骤一多，中间错一步，后面全歪，而且它不会主动喊停。</li></ul><p>补充一个判断幻觉风险的规律：<strong>越具体、越冷门、越依赖最新事实的内容，风险越高。</strong> 主流框架的标准用法它大概率对；某个小众库上周刚改的 API 签名，它大概率在凭记忆编。数字和引用同理——它给的页码、链接、统计数字，默认当作待核实处理。</p><h3 id="三、适用-vs-不适用" tabindex="-1">三、适用 vs 不适用 <a class="header-anchor" href="#三、适用-vs-不适用" aria-label="Permalink to “三、适用 vs 不适用”">​</a></h3><p><strong>放心用</strong>：头脑风暴、初稿生成、代码解释、文档总结、学习答疑、格式整理、非关键信息的检索起点。</p><p><strong>谨慎用</strong>：技术方案的最终决策、涉及数据一致性的代码、合同与法律条款、医疗与财务建议、面向客户的正式内容——这些场景 AI 可以做 80% 的初稿和分析，但最后 20% 必须人工把关。</p><p><strong>不要用</strong>：没有任何验证手段的结果（你无法判断对错的事）、涉及隐私却无法脱敏的数据、需要&quot;绝对正确&quot;的场景（生产配置、资金计算）。</p><p>一个简单的自测：<strong>如果 AI 这一步给错了，我能不能发现？</strong> 能发现，就放心让它做；发现不了，就自己做或者换一个能验证的方式。&quot;可发现错误&quot;是放手的资格，跟它答得漂不漂亮没关系。</p><h3 id="四、随任务升级的介入程度" tabindex="-1">四、随任务升级的介入程度 <a class="header-anchor" href="#四、随任务升级的介入程度" aria-label="Permalink to “四、随任务升级的介入程度”">​</a></h3><p>介入深度不该一刀切，跟着任务的出错代价走：</p><ul><li><strong>低风险</strong>（错了立刻能改）：让 AI 全程代劳，你只看最终结果——摘要、草稿、格式整理。</li><li><strong>中风险</strong>（错了要花时间才发现）：AI 起草，你逐段过一遍——代码实现、方案初稿、数据分析。</li><li><strong>高风险</strong>（错了代价大或难回滚）：AI 只做资料和选项，判断与执行你来——生产变更、资金相关、对外承诺。</li></ul><h3 id="五、人机分工的三条原则" tabindex="-1">五、人机分工的三条原则 <a class="header-anchor" href="#五、人机分工的三条原则" aria-label="Permalink to “五、人机分工的三条原则”">​</a></h3><ol><li><strong>AI 起草，人审查</strong>：把 AI 放在&quot;生成候选&quot;的位置，把人放在&quot;判断与拍板&quot;的位置。方向别反了。</li><li><strong>可验证的交给 AI，不可验证的留给人</strong>：代码能跑测试、事实能查原文的，让它做；无法验证对错的，人做。</li><li><strong>把 AI 当杠杆，不是替代</strong>：杠杆放大的是你已有的判断力。你懂业务，AI 帮你省下 70% 的执行时间；你不懂业务，AI 只会帮你更快地走向错误的方向。这也是为什么这个模块叫&quot;认知成长&quot;——认知不够，杠杆再长也撬不动东西。</li></ol><h3 id="六、几个常见误解" tabindex="-1">六、几个常见误解 <a class="header-anchor" href="#六、几个常见误解" aria-label="Permalink to “六、几个常见误解”">​</a></h3><ul><li><strong>误解：&quot;模型越强就不用核查了。&quot;</strong> 能力提升降低的是错误频率，不改变&quot;错了不自知&quot;这个性质。频率下降不等于可以不管。</li><li><strong>误解：&quot;它说得越自信越可靠。&quot;</strong> 语气自信是语言风格，不是置信度信号。它编造时和正确时的语气没有区别。</li><li><strong>误解：&quot;提示词写得神，就能让幻觉消失。&quot;</strong> 好提示能降低幻觉概率，但无法归零。把提示技巧当保险，是常见的过度信任。</li><li><strong>误解：&quot;AI 会取代我这个岗位。&quot;</strong> 更准确的说法是：会用 AI 的同行可能取代不会用的你。焦虑的解法是把杠杆借过来，而不是和杠杆较劲。</li><li><strong>误解：&quot;先等我学完原理再上手。&quot;</strong> 边界感是在使用中长出来的——踩过一次幻觉的坑，比读十页&quot;AI 会幻觉&quot;记得牢得多。</li></ul><h2 id="实践建议" tabindex="-1">实践建议 <a class="header-anchor" href="#实践建议" aria-label="Permalink to “实践建议”">​</a></h2><ol><li><strong>给关键输出设检查点</strong>：涉及数字、引用、API 用法的，强制自己做一次核对。核对成本远低于纠错成本。</li><li><strong>提示里主动要依据</strong>：要求&quot;给出结论时标注依据，不确定就说不确定&quot;，能明显降低幻觉带来的误导。</li><li><strong>重要任务拆小步</strong>：把大任务拆成 AI 每步都能被你快速验证的小步，而不是让它一口气输出一整份没人看得完的方案。</li><li><strong>记录踩坑案例</strong>：每次被 AI 坑了，记一句&quot;什么场景、它错在哪、我怎么发现的&quot;。攒十条，你就有了自己的边界地图。</li><li><strong>定期自问</strong>：这件事我是真的判断过，还是只是接受了 AI 的说法？答案经常不体面，但很有用。</li></ol><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to “小结”">​</a></h2><p>AI 不是天才，也不是骗子，它是一个能力有边界、错误有模式的工具。知道它擅长模式化生成，就知道什么该交给它；知道它会幻觉且不自知，就知道哪里必须设卡；知道杠杆要靠认知驱动，就知道为什么在用工具之前先要建立判断力。边界清楚了，用起来才会又快又稳。</p>',30)])])}const p=o(i,[["render",l]]);export{c as __pageData,p as default};
